// [Sync] Store-Entscheidung (Umsätze)
var arr=function(v){if(Array.isArray(v))return v;if(typeof v==='string'&&v.trim()){try{var p=JSON.parse(v);return Array.isArray(p)?p:[];}catch(e){return[];}}return[];};
var num=function(v){var n=parseFloat(v);return isFinite(n)?n:0;};
var recs=arr(input.records);
if(recs.length===0){
  return {case:'nomatch', ctx: JSON.stringify({resourceId:String(input.resourceId||''), type:'salesinvoice', matchKey:String(input.voucherNumber||'')})};
}
var rec=recs[0]; var recId=rec.id; var flds=rec.fields||{};
var netto=num(flds['fld0GMbvW8P8t25Nq']);
var current=String(flds['fldBavq4sjk2A1swZ']||'');
var vs=String(input.voucherStatus||'');
var ps=String(input.paymentStatus||'');
var items=arr(input.payItems);
var echte=items.filter(function(p){return p&&String(p.paymentItemType||'')!=='irrecoverableReceivable';});
var paidGross=echte.reduce(function(s,p){return s+num(p.amount);},0);
var partial=echte.length>0;
var tg=num(input.totalGross);
var frac=tg>0?Math.max(0,Math.min(1,paidGross/tg)):0;
var bezahlt=Math.round(netto*frac*100)/100;
if(vs==='voided'){return {case:'noop'};}
if(ps==='openRevenue'&&partial&&(current==='Offen'||current==='Überfällig'||current==='Angemahnt'||current==='Teilgezahlt')){
  return {case:'status_amount', recId:recId, status:'Teilgezahlt', bezahlt:bezahlt};
}
if(ps==='openRevenue'&&!partial&&current==='Teilgezahlt'){
  return {case:'status_amount', recId:recId, status:'Offen', bezahlt:bezahlt};
}
return {case:'amount', recId:recId, bezahlt:bezahlt};

// [Sync] Sales-Entscheidung (Auszahlungen) - Label + Bezahlt (brutto, anteilig)
var arr=function(v){if(Array.isArray(v))return v;if(typeof v==='string'&&v.trim()){try{var p=JSON.parse(v);return Array.isArray(p)?p:[];}catch(e){return[];}}return[];};
var num=function(v){var n=parseFloat(v);return isFinite(n)?n:0;};
var recs=arr(input.records);
if(recs.length===0){
  return {case:'nomatch', ctx: JSON.stringify({resourceId:String(input.resourceId||''), type:'purchaseinvoice', matchKey:String(input.resourceId||'')})};
}
var rec=recs[0]; var recId=rec.id; var flds=rec.fields||{};
var current=String(flds['fldd9jOWUYEpcwA4c']||'');
var vs=String(input.voucherStatus||'');
var ps=String(input.paymentStatus||'');
var items=arr(input.payItems);
var echte=items.filter(function(p){return p&&String(p.paymentItemType||'')!=='irrecoverableReceivable';});
var paidGross=Math.round(echte.reduce(function(s,p){return s+num(p.amount);},0)*100)/100;
var partial=echte.length>0;
if(vs==='voided'){return {case:'noop'};}
var status=null;
if(ps==='openExpense'&&partial&&current==='In Bearbeitung'){status='Teilzahlung';}
else if(ps==='openExpense'&&!partial&&current==='Teilzahlung'){status='In Bearbeitung';}
if(status){return {case:'status_amount', recId:recId, status:status, bezahlt:paidGross};}
return {case:'amount', recId:recId, bezahlt:paidGross};
